data.prompt:
{"id": "intersection_crash_frequency", "name": "Expected intersection crash frequency", "kind": "rate", "unit": "crashes/yr", "aggregation": "sum", "scales": "street, network", "definition": "Expected crashes per year from a safety performance function, Empirical Bayes-adjusted with history", "source": "AASHTO 2010 Highway Safety Manual"}
{"id": "perceived_comfort", "name": "Perceived comfort", "kind": "ordinal", "unit": "1–5 Likert", "aggregation": "wmean:visitors", "scales": "person, street, block", "definition": "Rated comfort of a public space (protection, places to sit, stand, see, talk)", "source": "Gehl 2010 (twelve quality criteria)"}
{"id": "perceived_integrity", "name": "Perceived integrity (trustworthiness)", "kind": "latent", "unit": "1–5 Likert", "aggregation": "wmean:population", "scales": "person, organisation", "definition": "Six items on whether the trustee adheres to acceptable principles and keeps promises", "source": "Mayer & Davis 1999 (ABI model)"}
{"id": "single_bidding_rate", "name": "Single-bidding rate", "kind": "ratio", "unit": "1", "aggregation": "ratio-of-sums:single_bid_contracts/contracts", "scales": "organisation, city, region, nation", "definition": "Share of competitive tenders receiving only one bid (a corruption-risk red flag)", "source": "Fazekas, Tóth & King 2016"}

{"id": "social_infrastructure_gap", "name": "Social infrastructure provision gap", "kind": "ratio", "unit": "1", "aggregation": "none", "scales": "neighbourhood,district,city", "definition": "(Standard provision per population − actual provision) / standard provision, by facility type", "source": "Local planning standards"}
{"id": "rockfall_hazard_rating", "name": "Rockfall Hazard Rating", "kind": "ordinal", "unit": "score 0–972 from 12 categories (3–81 each)", "aggregation": "max", "scales": "street,network", "definition": "Exponential scores for slope height, ditch, exposure, sight distance, geology, block size, climate and history, summed", "source": "Pierson 1990 (RHRS, Oregon DOT)"}
{"id": "pedestrian_crossing_delay", "name": "Pedestrian crossing delay", "kind": "duration", "unit": "s", "aggregation": "wmean:trips", "scales": "street", "definition": "Mean wait at a crossing; at signals d = (C − g)² / (2C)", "source": "HCM 2016"}
{"id": "traffic_conflict_rate", "name": "Traffic conflict rate", "kind": "rate", "unit": "serious conflicts per hour", "aggregation": "ratio-of-sums:conflicts/hours", "scales": "street", "definition": "Serious conflicts (time-to-collision or post-encroachment time below thresholds) observed per hour", "source": "Hydén 1987 (Swedish Traffic Conflict Technique)"}

{"id": "cso_spill_frequency", "name": "CSO spill frequency", "kind": "rate", "unit": "spills/yr", "aggregation": "sum", "scales": "network, city", "definition": "Number of combined sewer overflow events per year (with volume and duration)", "source": "EA Event Duration Monitoring; US EPA CSO Control Policy 1994"}
{"id": "hazard_intensity_measure", "name": "Hazard intensity measure", "kind": "physical", "unit": "units of the hazard (m flood depth, g PGA, m/s gust)", "aggregation": "max", "scales": "parcel,building,block,city", "definition": "Physical measure of a hazard at a site (flood depth, peak ground acceleration, gust speed, temperature)", "source": "UNDRR 2017 terminology; FEMA HAZUS"}
{"id": "transfer_penalty", "name": "Transfer penalty", "kind": "duration", "unit": "equivalent in-vehicle min", "aggregation": "none", "scales": "person, network", "definition": "Disutility of a transfer beyond its walking and waiting time, in equivalent in-vehicle minutes", "source": "Wardman 2004"}
{"id": "energy_not_supplied", "name": "Energy not supplied", "kind": "flow", "unit": "MWh per yr", "aggregation": "sum", "scales": "network,city,region", "definition": "Energy demanded but not delivered because of outages or rota load shedding", "source": "CIGRE; Billinton & Allan 1996"}

{"id": "news_perceived_walkability", "name": "Perceived walkability (NEWS)", "kind": "latent", "unit": "1–4 Likert", "aggregation": "wmean:population", "scales": "person, neighbourhood", "definition": "Neighborhood Environment Walkability Scale: subscales on density, mix, connectivity, infrastructure, aesthetics, safety", "source": "Saelens et al. 2003; Cerin et al. 2006 (NEWS-A)"}
{"id": "night_event_count", "name": "Night-time cultural events per week", "kind": "count", "unit": "events per week", "aggregation": "sum", "scales": "district,city", "definition": "Cultural events starting after 18:00 per week", "source": "GLA 2018 London at Night"}
{"id": "pefa_score", "name": "PEFA performance score", "kind": "ordinal", "unit": "grades A–D per indicator", "aggregation": "none", "scales": "city,region,nation", "definition": "31 indicators in seven pillars (credibility to audit) scored A–D by declared calibration", "source": "PEFA Framework 2016"}
{"id": "infrastructure_investment_gap", "name": "Infrastructure investment gap", "kind": "amount", "unit": "currency", "aggregation": "sum", "scales": "city, region, nation", "definition": "Investment need to a benchmark or target − projected investment on current trends", "source": "Global Infrastructure Hub 2017 (Infrastructure Outlook)"}

{"id": "japanese_proficiency_level", "name": "Japanese language proficiency level", "kind": "ordinal", "unit": "levels N5–N1 (JLPT)", "aggregation": "median", "scales": "person, organisation", "definition": "Certified level of Japanese proficiency (JLPT N5 lowest to N1 highest); business Japanese by BJT J5–J1+", "source": "Japan Foundation & JEES JLPT"}
{"id": "height_to_width_ratio", "name": "Street height-to-width ratio", "kind": "ratio", "unit": "1", "aggregation": "wmean:length", "scales": "street", "definition": "H/W = mean building height on both sides / street width wall to wall", "source": "Oke 1988; Ewing & Handy 2009"}
{"id": "benefit_shortfall_ratio", "name": "Benefit (demand) shortfall ratio", "kind": "ratio", "unit": "1", "aggregation": "recompute", "scales": "project", "definition": "(forecast − actual benefit or demand) / forecast", "source": "Flyvbjerg, Holm & Buhl 2005"}
{"id": "days_of_inventory_cover", "name": "Days of inventory cover", "kind": "duration", "unit": "days", "aggregation": "min", "scales": "firm,city,nation", "definition": "Stock on hand / mean daily consumption of a critical good", "source": "IEA 90-day stockholding rule; APICS"}

{"id": "intersection_crash_frequency", "name": "Expected intersection crash frequency", "kind": "rate", "unit": "crashes/yr", "aggregation": "sum", "scales": "street, network", "definition": "Expected crashes per year from a safety performance function, Empirical Bayes-adjusted with history", "source": "AASHTO 2010 Highway Safety Manual"}
{"id": "perceived_comfort", "name": "Perceived comfort", "kind": "ordinal", "unit": "1–5 Likert", "aggregation": "wmean:visitors", "scales": "person, street, block", "definition": "Rated comfort of a public space (protection, places to sit, stand, see, talk)", "source": "Gehl 2010 (twelve quality criteria)"}
{"id": "perceived_integrity", "name": "Perceived integrity (trustworthiness)", "kind": "latent", "unit": "1–5 Likert", "aggregation": "wmean:population", "scales": "person, organisation", "definition": "Six items on whether the trustee adheres to acceptable principles and keeps promises", "source": "Mayer & Davis 1999 (ABI model)"}
{"id": "single_bidding_rate", "name": "Single-bidding rate", "kind": "ratio", "unit": "1", "aggregation": "ratio-of-sums:single_bid_contracts/contracts", "scales": "organisation, city, region, nation", "definition": "Share of competitive tenders receiving only one bid (a corruption-risk red flag)", "source": "Fazekas, Tóth & King 2016"}

{"id": "seating_capacity", "name": "Seating capacity (primary and secondary)", "kind": "count", "unit": "seats", "aggregation": "sum", "scales": "street,block,neighbourhood", "definition": "Primary seats plus secondary seating (ledges, steps) counted at 1 seat per 0.6 m of sittable edge", "source": "Whyte 1980"}
{"id": "urban_primacy_index", "name": "Urban primacy index", "kind": "ratio", "unit": "1", "aggregation": "recompute", "scales": "region, nation", "definition": "Population of the largest city / urban population (or / the next three cities)", "source": "Jefferson 1939; Henderson 2003"}
{"id": "trust_in_government", "name": "Trust in (local) government", "kind": "ordinal", "unit": "0–10", "aggregation": "wmean:population", "scales": "city, region, nation", "definition": "'How much do you trust the local government?' on 0–10; share with high trust (6–10)", "source": "OECD 2021 Trust Survey; OECD 2017 Guidelines on Measuring Trust"}
{"id": "land_administration_quality_index", "name": "Quality of land administration index", "kind": "composite", "unit": "0–30", "aggregation": "none", "scales": "city,nation", "definition": "Sum of scores on reliability of infrastructure, transparency, coverage, dispute resolution and equal access", "source": "World Bank Doing Business 2020"}

{"id": "necessity_consistency", "name": "Consistency of necessity (fuzzy sets)", "kind": "ratio", "unit": "[0,1]", "aggregation": "recompute", "scales": "project", "definition": "Cons(Y ⊆ X) = Σ min(x_i, y_i) / Σ y_i", "source": "Ragin 2006"}
{"id": "measurement_invariance_level", "name": "Measurement invariance level", "kind": "ordinal", "unit": "levels: none, configural, metric, scalar, strict", "aggregation": "min", "scales": "project", "definition": "Highest level of equality of a measurement model across groups not rejected (e.g. ΔCFI ≤ 0.01)", "source": "Vandenberg & Lance 2000; Chen 2007"}
{"id": "activity_density", "name": "Activity density", "kind": "density", "unit": "(residents + jobs)/km²", "aggregation": "ratio-of-sums:residents_and_jobs/area", "scales": "block, neighbourhood, city", "definition": "(population + employment) / land area", "source": "Ewing & Cervero 2010"}
{"id": "high_tide_flooding_frequency", "name": "High-tide flooding frequency", "kind": "rate", "unit": "days per yr", "aggregation": "max", "scales": "street,neighbourhood,city", "definition": "Days per year with water level above a local minor-flood threshold at a tide gauge", "source": "Sweet et al. 2018 (NOAA)"}

{"id": "resident_attitude_to_tourism", "name": "Resident attitude to tourism (TIAS)", "kind": "latent", "unit": "1–5 Likert", "aggregation": "wmean:population", "scales": "neighbourhood, city", "definition": "Latent factors of the Tourism Impact Attitude Scale (27 items: costs and benefits)", "source": "Lankford & Howard 1994"}
{"id": "fuel_reserve_days", "name": "Fuel reserve days", "kind": "duration", "unit": "days", "aggregation": "min", "scales": "organisation,city,nation", "definition": "Stocks of fuel / average daily consumption", "source": "IEA emergency stock obligation (90 days)"}
{"id": "risk_rating", "name": "Risk rating", "kind": "ordinal", "unit": "levels (e.g. low, medium, high, extreme from a 5 × 5 matrix)", "aggregation": "max", "scales": "building, project, organisation, city", "definition": "Likelihood level × consequence level read from a declared risk matrix", "source": "ISO 31000:2018; IEC 31010:2019"}
{"id": "average_online_rating", "name": "Average online rating", "kind": "ordinal", "unit": "1–5 stars", "aggregation": "wmean:visitors", "scales": "firm, street, neighbourhood", "definition": "Mean star rating with count of reviews on a review platform", "source": "Luca 2016"}

{"id": "availability_ratio", "name": "Availability", "kind": "ratio", "unit": "[0,1]", "aggregation": "ratio-of-sums:uptime/total_time", "scales": "building,network,organisation", "definition": "A = MTBF / (MTBF + MTTR), or uptime / total time", "source": "IEC 60050-192"}
{"id": "project_outcome_rating", "name": "Project outcome rating", "kind": "ordinal", "unit": "6 levels: highly unsatisfactory–highly satisfactory", "aggregation": "median", "scales": "project, organisation", "definition": "Rating of a project's relevance, efficacy and efficiency against its objectives on a six-point scale", "source": "World Bank IEG 2017"}
{"id": "getis_ord_gi_star", "name": "Getis–Ord Gi* statistic", "kind": "spatial-statistic", "unit": "z-score", "aggregation": "recompute", "scales": "block, neighbourhood, city", "definition": "Gi* = (Σ_j w_ij x_j − x̄ Σ_j w_ij) / (s √[(n Σ w_ij² − (Σ w_ij)²)/(n − 1)])", "source": "Getis & Ord 1992; Ord & Getis 1995"}
{"id": "import_penetration_exposure", "name": "Import penetration exposure (shift-share)", "kind": "coefficient", "unit": "currency per worker", "aggregation": "wmean:workers", "scales": "city,metro,region", "definition": "ΔIPW_r = Σ_j (L_rj/L_r) ΔM_j / L_j: local exposure to import growth by industry", "source": "Autor, Dorn & Hanson 2013"}

{"id": "market_stall_fee", "name": "Market stall fee", "kind": "price", "unit": "currency/day", "aggregation": "median", "scales": "street,district,city", "definition": "Daily fee charged for a stall or vending pitch", "source": "Municipal market regulations"}
{"id": "green_view_index", "name": "Green View Index", "kind": "ratio", "unit": "1", "aggregation": "wmean:length", "scales": "street,neighbourhood,district", "definition": "Share of vegetation pixels in street-level images sampled at points in several directions", "source": "Li et al. 2015"}
{"id": "sense_of_place", "name": "Sense of place", "kind": "latent", "unit": "1–5 Likert", "aggregation": "wmean:population", "scales": "person, neighbourhood, city", "definition": "Attitudinal scale over place identity, attachment and dependence items", "source": "Jorgensen & Stedman 2001"}
{"id": "perceived_safety", "name": "Perceived safety", "kind": "ordinal", "unit": "1–4 (very safe – very unsafe)", "aggregation": "wmean:population", "scales": "person, neighbourhood, city", "definition": "'How safe do you feel walking alone in your area after dark?' (SDG 16.1.4)", "source": "SDG 16.1.4; UNODC"}

{"id": "place_identity", "name": "Place identity", "kind": "latent", "unit": "1–5 Likert", "aggregation": "wmean:population", "scales": "person, neighbourhood", "definition": "Subscale of place attachment: items on how much a place is part of oneself", "source": "Williams & Vaske 2003"}
{"id": "total_addressable_market", "name": "Total addressable market", "kind": "flow", "unit": "currency/yr", "aggregation": "sum", "scales": "city, region, nation", "definition": "Revenue if every potential customer bought: potential buyers × annual spend per buyer", "source": "Blank & Dorf 2012"}
{"id": "total_factor_productivity", "name": "Total factor productivity", "kind": "coefficient", "unit": "1 (index)", "aggregation": "recompute", "scales": "firm, region, nation", "definition": "Solow residual: ln A = ln Y − α ln K − (1−α) ln L", "source": "Solow 1957"}
{"id": "perceived_ability", "name": "Perceived ability (trustworthiness)", "kind": "latent", "unit": "1–5 Likert", "aggregation": "wmean:population", "scales": "person, organisation", "definition": "Six items on the trustee's skills and competence in the relevant domain", "source": "Mayer & Davis 1999 (ABI model)"}

{"id": "pima_score", "name": "Public investment management assessment score", "kind": "ordinal", "unit": "15 institutions rated low–medium–high", "aggregation": "median", "scales": "city, nation", "definition": "Ratings of institutional design and effectiveness over planning, allocation and implementation of public investment", "source": "IMF 2018 PIMA Handbook"}
{"id": "benefit_concentration_coefficient", "name": "Concentration coefficient of public benefits", "kind": "distribution", "unit": "[−1,1]", "aggregation": "recompute", "scales": "city,region,nation", "definition": "C = 1 − 2∫ L_B(p) dp, benefits ranked by income", "source": "Lustig 2018 (CEQ); Kakwani 1977"}
{"id": "perceived_social_norm", "name": "Perceived social norm", "kind": "latent", "unit": "1–7 Likert", "aggregation": "wmean:population", "scales": "person, neighbourhood, city", "definition": "Mean of items on descriptive (what others do) and injunctive (what others approve) norms for a behaviour", "source": "Cialdini, Reno & Kallgren 1990"}
{"id": "protest_event_count", "name": "Protest event count", "kind": "count", "unit": "events per period", "aggregation": "sum", "scales": "neighbourhood,city,region,nation", "definition": "Number of protest events coded from news or event data in a period and area", "source": "Tilly 1978; Raleigh et al. 2010 (ACLED)"}

{"id": "vendor_net_income", "name": "Street vendor net income", "kind": "flow", "unit": "currency/day", "aggregation": "median", "scales": "person,street,city", "definition": "Daily sales minus costs of goods, fees and transport for a vendor", "source": "WIEGO Informal Economy Monitoring Study 2014"}
{"id": "multidimensional_poverty_index", "name": "Multidimensional poverty index", "kind": "composite", "unit": "[0,1]", "aggregation": "decomposable", "scales": "household, neighbourhood, city, region, nation", "definition": "MPI = H × A: headcount of those deprived in ≥ 1/3 of weighted indicators × average intensity", "source": "Alkire & Foster 2011; UNDP–OPHI global MPI"}
{"id": "drainage_capacity_return_period", "name": "Drainage design return period", "kind": "duration", "unit": "yr (return period)", "aggregation": "min", "scales": "street,neighbourhood,city", "definition": "Return period of the design storm a drainage network conveys without surcharge or flooding", "source": "EN 752:2017"}
{"id": "theil_index", "name": "Theil index", "kind": "distribution", "unit": "nats", "aggregation": "decomposable", "scales": "neighbourhood, city, metro, region, nation", "definition": "T = (1/n) Σ_i (y_i/ȳ) ln(y_i/ȳ) = Σ_g s_g T_g + Σ_g s_g ln(ȳ_g/ȳ)", "source": "Theil 1967"}

{"id": "heat_exposure_person_days", "name": "Heat exposure (person-days)", "kind": "count", "unit": "person-days per yr", "aggregation": "sum", "scales": "neighbourhood,city,region", "definition": "Persons × days with heat index (or WBGT) above a declared threshold", "source": "Tuholske et al. 2021"}
{"id": "liquefaction_potential_index", "name": "Liquefaction potential index", "kind": "composite", "unit": "0–100", "aggregation": "max", "scales": "parcel,block,neighbourhood", "definition": "LPI = ∫_0^20 m F(z) w(z) dz, F = 1 − FS where FS < 1, w(z) = 10 − 0.5z", "source": "Iwasaki et al. 1978"}
{"id": "active_travel_time", "name": "Active travel time", "kind": "duration", "unit": "min/person/day", "aggregation": "wmean:population", "scales": "person, neighbourhood, city", "definition": "Mean minutes per day walking and cycling for transport", "source": "WHO HEAT 2017 (Kahlmeier et al.)"}
{"id": "cultural_intelligence_scale", "name": "Cultural intelligence scale (CQS)", "kind": "latent", "unit": "1–7 Likert", "aggregation": "wmean:population", "scales": "person, organisation", "definition": "20 items over metacognitive, cognitive, motivational and behavioural cultural intelligence", "source": "Ang et al. 2007"}

{"id": "trust_in_science", "name": "Trust in science and experts", "kind": "latent", "unit": "index (high, medium, low)", "aggregation": "median", "scales": "person,nation", "definition": "Latent index from items on trust in scientists, doctors and science information", "source": "Wellcome Global Monitor 2018"}
{"id": "exposed_asset_value", "name": "Exposed asset value", "kind": "amount", "unit": "currency", "aggregation": "sum", "scales": "building,block,neighbourhood,city,region", "definition": "Replacement value of buildings and infrastructure within a hazard footprint", "source": "UNDRR 2017; GEM exposure models"}
{"id": "container_dwell_time", "name": "Container dwell time", "kind": "duration", "unit": "days", "aggregation": "median", "scales": "network,nation", "definition": "Days import containers stay in the terminal from discharge to gate-out", "source": "World Bank Container Port Performance Index"}
{"id": "wetland_area", "name": "Wetland area", "kind": "amount", "unit": "ha", "aggregation": "sum", "scales": "city,region", "definition": "Area of wetlands (natural and restored)", "source": "Ramsar; SDG 6.6.1"}

{"id": "vendor_net_income", "name": "Street vendor net income", "kind": "flow", "unit": "currency/day", "aggregation": "median", "scales": "person,street,city", "definition": "Daily sales minus costs of goods, fees and transport for a vendor", "source": "WIEGO Informal Economy Monitoring Study 2014"}
{"id": "multidimensional_poverty_index", "name": "Multidimensional poverty index", "kind": "composite", "unit": "[0,1]", "aggregation": "decomposable", "scales": "household, neighbourhood, city, region, nation", "definition": "MPI = H × A: headcount of those deprived in ≥ 1/3 of weighted indicators × average intensity", "source": "Alkire & Foster 2011; UNDP–OPHI global MPI"}
{"id": "drainage_capacity_return_period", "name": "Drainage design return period", "kind": "duration", "unit": "yr (return period)", "aggregation": "min", "scales": "street,neighbourhood,city", "definition": "Return period of the design storm a drainage network conveys without surcharge or flooding", "source": "EN 752:2017"}
{"id": "theil_index", "name": "Theil index", "kind": "distribution", "unit": "nats", "aggregation": "decomposable", "scales": "neighbourhood, city, metro, region, nation", "definition": "T = (1/n) Σ_i (y_i/ȳ) ln(y_i/ȳ) = Σ_g s_g T_g + Σ_g s_g ln(ȳ_g/ȳ)", "source": "Theil 1967"}

{"id": "necessity_consistency", "name": "Consistency of necessity (fuzzy sets)", "kind": "ratio", "unit": "[0,1]", "aggregation": "recompute", "scales": "project", "definition": "Cons(Y ⊆ X) = Σ min(x_i, y_i) / Σ y_i", "source": "Ragin 2006"}
{"id": "measurement_invariance_level", "name": "Measurement invariance level", "kind": "ordinal", "unit": "levels: none, configural, metric, scalar, strict", "aggregation": "min", "scales": "project", "definition": "Highest level of equality of a measurement model across groups not rejected (e.g. ΔCFI ≤ 0.01)", "source": "Vandenberg & Lance 2000; Chen 2007"}
{"id": "activity_density", "name": "Activity density", "kind": "density", "unit": "(residents + jobs)/km²", "aggregation": "ratio-of-sums:residents_and_jobs/area", "scales": "block, neighbourhood, city", "definition": "(population + employment) / land area", "source": "Ewing & Cervero 2010"}
{"id": "high_tide_flooding_frequency", "name": "High-tide flooding frequency", "kind": "rate", "unit": "days per yr", "aggregation": "max", "scales": "street,neighbourhood,city", "definition": "Days per year with water level above a local minor-flood threshold at a tide gauge", "source": "Sweet et al. 2018 (NOAA)"}

{"id": "perceived_distributive_justice", "name": "Perceived distributive justice", "kind": "latent", "unit": "1–5 Likert", "aggregation": "wmean:population", "scales": "person, organisation, city", "definition": "Four items on whether outcomes reflect effort, contribution and what is deserved", "source": "Colquitt 2001"}
{"id": "heritage_significance_rating", "name": "Heritage significance rating", "kind": "ordinal", "unit": "levels (exceptional, high, moderate, little) per value", "aggregation": "max", "scales": "building,street,district", "definition": "Assessment of aesthetic, historic, scientific, social and spiritual value for past, present and future generations", "source": "Burra Charter 2013 (Australia ICOMOS); Historic England 2008 Conservation Principles"}
{"id": "conversion_completions", "name": "Dwellings created by change of use", "kind": "flow", "unit": "dwellings per yr", "aggregation": "sum", "scales": "district,city,nation", "definition": "Net additional dwellings from conversion of non-residential buildings in the year", "source": "DLUHC net additional dwellings statistics"}
{"id": "global_power_city_index", "name": "Global Power City Index", "kind": "composite", "unit": "score", "aggregation": "none", "scales": "city", "definition": "Sum of normalised indicators in six functions: economy, R&D, cultural interaction, livability, environment, accessibility", "source": "Mori Memorial Foundation GPCI"}

{"id": "news_perceived_walkability", "name": "Perceived walkability (NEWS)", "kind": "latent", "unit": "1–4 Likert", "aggregation": "wmean:population", "scales": "person, neighbourhood", "definition": "Neighborhood Environment Walkability Scale: subscales on density, mix, connectivity, infrastructure, aesthetics, safety", "source": "Saelens et al. 2003; Cerin et al. 2006 (NEWS-A)"}
{"id": "night_event_count", "name": "Night-time cultural events per week", "kind": "count", "unit": "events per week", "aggregation": "sum", "scales": "district,city", "definition": "Cultural events starting after 18:00 per week", "source": "GLA 2018 London at Night"}
{"id": "pefa_score", "name": "PEFA performance score", "kind": "ordinal", "unit": "grades A–D per indicator", "aggregation": "none", "scales": "city,region,nation", "definition": "31 indicators in seven pillars (credibility to audit) scored A–D by declared calibration", "source": "PEFA Framework 2016"}
{"id": "infrastructure_investment_gap", "name": "Infrastructure investment gap", "kind": "amount", "unit": "currency", "aggregation": "sum", "scales": "city, region, nation", "definition": "Investment need to a benchmark or target − projected investment on current trends", "source": "Global Infrastructure Hub 2017 (Infrastructure Outlook)"}

{"id": "perceived_value", "name": "Perceived value (PERVAL)", "kind": "latent", "unit": "1–7 Likert", "aggregation": "wmean:visitors", "scales": "person, firm, street", "definition": "Latent factors over 19 items: quality, emotional, price and social value", "source": "Sweeney & Soutar 2001"}
{"id": "ai_risk_class", "name": "AI system risk class", "kind": "ordinal", "unit": "unacceptable, high, limited, minimal", "aggregation": "max", "scales": "project,organisation", "definition": "Class by intended use under the EU AI Act annexes", "source": "EU AI Act 2024 (Regulation 2024/1689)"}
{"id": "crash_modification_factor", "name": "Crash modification factor", "kind": "coefficient", "unit": "1", "aggregation": "none", "scales": "street", "definition": "CMF = expected crashes with treatment / without (empirical Bayes before–after)", "source": "AASHTO HSM 2010; FHWA CMF Clearinghouse"}
{"id": "peak_electricity_load", "name": "Peak electricity load", "kind": "flow", "unit": "MW", "aggregation": "max", "scales": "building, network, city", "definition": "Maximum demand over a period (annual or daily peak)", "source": "IEA energy statistics"}

{"id": "procurement_publication_rate", "name": "Procurement publication rate", "kind": "ratio", "unit": "1", "aggregation": "ratio-of-sums:published/contracts", "scales": "organisation,city,nation", "definition": "Share of procurement (by value) published with notices and award data", "source": "EU Single Market Scoreboard; OCDS"}
{"id": "hours_of_water_supply", "name": "Continuity of water supply", "kind": "duration", "unit": "h per day", "aggregation": "wmean:population", "scales": "neighbourhood,network,city", "definition": "Average hours per day that piped water is available at the tap", "source": "IBNET (World Bank)"}
{"id": "closeness_centrality", "name": "Closeness centrality", "kind": "network", "unit": "1", "aggregation": "recompute", "scales": "street,network", "definition": "C_C(i) = (N − 1)/Σ_j d_ij", "source": "Sabidussi 1966"}
{"id": "wage_growth_rate", "name": "Wage growth rate", "kind": "rate", "unit": "1/yr", "aggregation": "recompute", "scales": "city, region, nation", "definition": "Δ ln median hourly earnings, year on year", "source": "ILO Global Wage Report"}

{"id": "privacy_loss_epsilon", "name": "Privacy-loss budget (ε)", "kind": "coefficient", "unit": "1", "aggregation": "sum", "scales": "project,organisation", "definition": "Pr[M(D) ∈ S] ≤ e^ε · Pr[M(D′) ∈ S] for datasets differing in one record", "source": "Dwork et al. 2006"}
{"id": "social_cohesion_scale", "name": "Social cohesion and trust scale", "kind": "latent", "unit": "1–5 Likert", "aggregation": "wmean:population", "scales": "neighbourhood, city", "definition": "Mean of 5 items (close-knit, willing to help, can be trusted, get along, share values)", "source": "Sampson, Raudenbush & Earls 1997"}
{"id": "perceived_legitimacy", "name": "Perceived legitimacy", "kind": "latent", "unit": "1–5 Likert scale score", "aggregation": "wmean:population", "scales": "person,neighbourhood,city,nation", "definition": "Latent score from items on obligation to obey, trust and normative alignment with an authority or reform", "source": "Tyler 2006; Gilley 2006"}
{"id": "wharton_residential_land_use_regulatory_index", "name": "Wharton Residential Land Use Regulatory Index", "kind": "composite", "unit": "std. units", "aggregation": "none", "scales": "city, metro", "definition": "Factor score over survey sub-indices (approval delay, zoning votes, density restrictions, open-space and exaction requirements)", "source": "Gyourko, Saiz & Summers 2008; Gyourko, Hartley & Krimmel 2021"}

{"id": "remaining_useful_life", "name": "Remaining useful life", "kind": "duration", "unit": "yr", "aggregation": "min", "scales": "building,network", "definition": "Expected time until an asset can no longer perform its function", "source": "ISO 13381-1:2015"}
{"id": "land_surface_temperature", "name": "Land surface temperature", "kind": "physical", "unit": "K", "aggregation": "wmean:area", "scales": "parcel,block,neighbourhood,district,city", "definition": "Radiometric skin temperature from thermal infrared, emissivity-corrected (split-window)", "source": "Wan & Dozier 1996"}
{"id": "institutional_feasibility_rating", "name": "Institutional feasibility rating", "kind": "ordinal", "unit": "levels 1–5", "aggregation": "min", "scales": "project,organisation,city", "definition": "Rubric on mandate, capacity, coordination and resources needed to implement an option", "source": "Bardach & Patashnik 2019"}
{"id": "snow_clearance_time", "name": "Snow and ice clearance time", "kind": "duration", "unit": "hours", "aggregation": "max", "scales": "network,city", "definition": "Hours after a storm until priority routes are cleared to standard", "source": "APWA winter maintenance metrics"}

{"id": "wet_bulb_globe_temperature", "name": "Wet-bulb globe temperature", "kind": "physical", "unit": "°C", "aggregation": "max", "scales": "street, block, city", "definition": "WBGT = 0.7 T_nw + 0.2 T_g + 0.1 T_a (outdoors in sun)", "source": "ISO 7243:2017"}
{"id": "street_illuminance", "name": "Street illuminance", "kind": "physical", "unit": "lux", "aggregation": "min", "scales": "street,neighbourhood", "definition": "Maintained average horizontal illuminance on the footway (EN 13201 P-classes)", "source": "EN 13201-2:2015"}
{"id": "perceived_crowding", "name": "Perceived crowding", "kind": "ordinal", "unit": "1–9 scale", "aggregation": "median", "scales": "street, neighbourhood", "definition": "Single item from 1 (not at all crowded) to 9 (extremely crowded)", "source": "Shelby, Vaske & Heberlein 1989"}
{"id": "luminance_contrast_ratio", "name": "Luminance contrast ratio", "kind": "ratio", "unit": "1", "aggregation": "min", "scales": "building,street", "definition": "CR = (L1 + 0.05)/(L2 + 0.05) on relative luminance; ≥ 4.5 for text", "source": "W3C WCAG 2.1"}

{"id": "nearest_neighbour_index", "name": "Average nearest neighbour index", "kind": "spatial-statistic", "unit": "1", "aggregation": "recompute", "scales": "street, neighbourhood, city", "definition": "R = observed mean nearest-neighbour distance / expected under CSR (0.5 / √density); R < 1 clustered", "source": "Clark & Evans 1954"}
{"id": "economic_net_present_value", "name": "Economic net present value", "kind": "valuation", "unit": "currency", "aggregation": "sum", "scales": "project", "definition": "ENPV: NPV of economic flows at shadow prices and the social discount rate", "source": "European Commission 2014 Guide to CBA"}
{"id": "destination_image", "name": "Destination image", "kind": "latent", "unit": "1–7 Likert", "aggregation": "wmean:visitors", "scales": "city, region", "definition": "Latent attributes (functional–psychological, common–unique) from structured items and open questions", "source": "Echtner & Ritchie 1991"}
{"id": "avoided_damage", "name": "Avoided damage (expected annual)", "kind": "valuation", "unit": "currency/yr", "aggregation": "sum", "scales": "building, project, city", "definition": "EAD_without − EAD_with, EAD = ∫ D(p) dp over annual exceedance probability", "source": "Penning-Rowsell et al. 2013 (Multi-Coloured Manual)"}

{"id": "spf_predicted_crash_frequency", "name": "Predicted crash frequency (safety performance function)", "kind": "rate", "unit": "crashes per km per yr", "aggregation": "sum", "scales": "street,network", "definition": "N = exp(α) × AADT^β × L, adjusted by CMFs", "source": "AASHTO HSM 2010"}
{"id": "conflict_escalation_level", "name": "Conflict escalation level", "kind": "ordinal", "unit": "stages 1–9 (Glasl)", "aggregation": "max", "scales": "project,neighbourhood,organisation", "definition": "Stage from hardening and debate through coalitions, loss of face and threats to destruction", "source": "Glasl 1982"}
{"id": "consumer_trust", "name": "Consumer trust", "kind": "latent", "unit": "1–7 Likert", "aggregation": "wmean:visitors", "scales": "person, firm", "definition": "Latent factor over items on confidence in a seller's reliability and integrity", "source": "Morgan & Hunt 1994"}
{"id": "built_up_area_growth_rate", "name": "Built-up area growth rate", "kind": "rate", "unit": "per yr", "aggregation": "recompute", "scales": "city,metro", "definition": "Annual log change in built-up area: ln(A₂/A₁)/(t₂ − t₁)", "source": "Angel et al. 2011"}

{"id": "dwell_time", "name": "Dwell time", "kind": "duration", "unit": "min", "aggregation": "wmean:visitors", "scales": "building, street, neighbourhood", "definition": "Mean (or median) time a visitor stays in a place per visit", "source": "Gehl & Svarre 2013"}
{"id": "pedestrian_level_of_service", "name": "Pedestrian level of service", "kind": "ordinal", "unit": "grades A–F", "aggregation": "median", "scales": "street", "definition": "Grade from pedestrian space (m² per person) or flow rate on walkways, by HCM thresholds", "source": "HCM 2016; Fruin 1971"}
{"id": "irridex_stage", "name": "Resident irritation stage (Irridex)", "kind": "ordinal", "unit": "4 stages (euphoria, apathy, annoyance, antagonism)", "aggregation": "median", "scales": "neighbourhood,city", "definition": "Stage of resident response to tourism growth", "source": "Doxey 1975"}
{"id": "ecommerce_share_of_retail", "name": "E-commerce share of retail sales", "kind": "ratio", "unit": "1", "aggregation": "ratio-of-sums:online_sales/retail_sales", "scales": "city,region,nation", "definition": "Retail sales made online / total retail sales", "source": "US Census Bureau Quarterly E-Commerce Report"}
